fragment Mtl_FragmentOut xlatMtlMain(
    constant FGlobals_Type& FGlobals [[ buffer(0) ]],
    constant UnityPerMaterial_Type& UnityPerMaterial [[ buffer(1) ]],
    sampler sampler_MainTex [[ sampler (0) ]],
    sampler sampler_FlareTex [[ sampler (1) ]],
    texture2d<float, access::sample > _MainTex [[ texture(0) ]] ,
    texture2d<float, access::sample > _FlareTex [[ texture(1) ]] ,
    Mtl_FragmentIn input [[ stage_in ]])
{
    Mtl_FragmentOut output;
    float2 u_xlat0;
    float4 u_xlat1;
    float3 u_xlat2;
    float u_xlat4;
    float u_xlat6;
    u_xlat0.x = input.TEXCOORD1.w * 0.0500000007;
    u_xlat0.x = fma(input.TEXCOORD1.x, UnityPerMaterial._UflareScale, u_xlat0.x);
    u_xlat4 = input.TEXCOORD1.w * UnityPerMaterial._VflareSpeed;
    u_xlat6 = _MainTex.sample(sampler_MainTex, input.TEXCOORD0.xy, bias(FGlobals._GlobalMipBias.xyxx.x)).x;
    u_xlat6 = u_xlat6 * UnityPerMaterial._Intensity;
    u_xlat6 = u_xlat6 * 1.20000005;
    u_xlat0.y = fma(u_xlat6, UnityPerMaterial._VflareScale, u_xlat4);
    u_xlat0.x = _FlareTex.sample(sampler_FlareTex, u_xlat0.xy, bias(FGlobals._GlobalMipBias.xyxx.x)).x;
    u_xlat0.x = fma(u_xlat0.x, input.TEXCOORD1.z, u_xlat6);
    u_xlat0.x = dot(u_xlat0.xx, float2(u_xlat6));
    u_xlat0.x = u_xlat0.x * UnityPerMaterial._FlareIntensity;
    u_xlat2.xyz = fma(UnityPerMaterial._HiColor.xyz, u_xlat0.xxx, (-UnityPerMaterial._Color.xyz));
    u_xlat2.xyz = fma(u_xlat0.xxx, u_xlat2.xyz, UnityPerMaterial._Color.xyz);
    u_xlat1.xyz = u_xlat2.xyz * float3(UnityPerMaterial._ColorIntensity);
    u_xlat2.x = input.TEXCOORD1.z + -1.0;
    u_xlat2.x = fma(UnityPerMaterial._ColorAlphaWeight, u_xlat2.x, 1.0);
    u_xlat1.w = u_xlat2.x * u_xlat0.x;
    output.SV_Target0 = u_xlat1 * UnityPerMaterial._Colorize;
    return output;
}

